```cpp
#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

int main() {
    int n;
    cin >> n;

    vector<pair<int, int>> meetings(n);
    for (int i = 0; i < n; i++) {
        cin >> meetings[i].first >> meetings[i].second; // 시작, 종료
    }

    // 종료 시간 기준 정렬, 같으면 시작 시간 기준
    sort(meetings.begin(), meetings.end(), [](const pair<int,int>& a, const pair<int,int>& b) {
        if (a.second != b.second) return a.second < b.second;
        return a.first < b.first;
    });

    int count = 0, end = 0;
    for (auto& m : meetings) {
        if (m.first >= end) {
            count++;
            end = m.second;
        }
    }

    cout << count << "\n";
    return 0;
}
